/** آدرس عکس (برای پس‌زمینه)؛ اگر نبود، رشته‌ی خالی. */
function sp_img_url( $name ) {
	foreach ( array( 'webp', 'jpg', 'jpeg', 'png' ) as $ext ) {
		$rel = '/assets/img/' . $name . '.' . $ext;
		if ( file_exists( SP_DIR . $rel ) ) {
			return SP_URI . $rel;
		}
	}
	return '';
}

/** عکس کارت/سرآغاز یک آموزش: عکس شاخص وردپرس، وگرنه عکس پوسته (متای _sp_img). */
function sp_post_img( $post_id, $class = '', $eager = false, $sizes = '' ) {
	if ( has_post_thumbnail( $post_id ) ) {
		$attr = array( 'class' => $class, 'loading' => $eager ? 'eager' : 'lazy', 'decoding' => 'async' );
		if ( $eager ) {
			$attr['fetchpriority'] = 'high';
		}
		if ( $sizes ) {
			$attr['sizes'] = $sizes;
		}
		return get_the_post_thumbnail( $post_id, 'full', $attr );
	}
	$name = get_post_meta( $post_id, '_sp_img', true );
	return sp_img( $name ? $name : 'hero-cake', get_the_title( $post_id ), $class, $eager );
}

/** زمان تقریبی خواندن (دقیقه). */
function sp_read_minutes( $post_id ) {
	$words = count( preg_split( '/\s+/u', wp_strip_all_tags( get_post_field( 'post_content', $post_id ) ), -1, PREG_SPLIT_NO_EMPTY ) );
	return max( 1, (int) round( $words / 120 ) );
}

